export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = sdk.clamp(time, 0, 2 * T);
  const yT = u * t - g * t * t / 2;
  const vT = u - g * t;
  const rel = t >= T - 1e-9;
  const tau = Math.max(0, t - T);
  const vD = rel ? -g * tau : 0;
  const aD = rel ? -g : 0;
  const yD = rel ? H - g * tau * tau / 2 : H;
  const sy = sdk.linear([0, 2.2], [350, 90]);
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 10, y: 40, w: 305, h: 370, title: 'Toss', state: t < 1e-9 ? 'At launch' : (Math.abs(t - T) < 1e-9 ? 'At the top' : (t < T ? 'Rising' : (t > 2 * T - 1e-9 ? 'At launch height' : 'Falling'))), role: 'input' }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 325, y: 40, w: 305, h: 370, title: 'Drop', state: !rel ? 'Held in place' : (tau < 0.05 ? 'Just released' : (t > 2 * T - 1e-9 ? 'At launch height' : 'Falling together')), role: 'output' }));
  o.push(...sdk.groundMark('mark.toss', 162, 350, 120, '0 m'));
  o.push(...sdk.groundMark('mark.drop', 477, 350, 120, '0 m'));
  o.push(...sdk.gate('gate.drop', 477, sy(H) + 20, { open: rel }));
  if (rel) o.push({ kind: 'circle', id: 'ghost.drop', x: 477, y: sy(H), w: 28, opacity: 0.25 });
  const cx1 = 162, cx2 = 477, sc = 8;
  o.push(sdk.circle('ball.toss', cx1, sy(yT), 28));
  o.push(sdk.circle('ball.drop', cx2, sy(yD), 28));
  o.push(...sdk.vector('vec.v.toss', { x: cx1 - 30, y: sy(yT) }, { value: vT, direction: 'up' }, { scale: sc, label: 'v' }));
  o.push(...sdk.vector('vec.v.drop', { x: cx2 - 30, y: sy(yD) }, { value: vD, direction: 'up' }, { scale: sc, label: 'v' }));
  o.push(...sdk.vector('vec.a.toss', { x: cx1 + 30, y: sy(yT) }, { value: -g, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.vector('vec.a.drop', { x: cx2 + 30, y: sy(yD) }, { value: aD, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.callout(cx1 + 50, sy(yT) - 40, ['v ' + sdk.format(vT, 2) + ' m/s', 'a ' + sdk.format(-g, 1) + ' m/s^2'], { id: 'callout.toss' }));
  o.push(...sdk.callout(cx2 + 50, sy(yD) - 40, ['v ' + sdk.format(vD, 2) + ' m/s', 'a ' + sdk.format(aD, 1) + ' m/s^2'], { id: 'callout.drop' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'tossedVelocity', value: vT }, { id: 'tossedAcceleration', value: -g }, { id: 'dropVelocity', value: vD }, { id: 'dropAcceleration', value: aD }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vT, tossedAcceleration: -g, tossedHeight: yT, dropVelocity: vD, dropAcceleration: aD, dropHeight: yD }
  };
}
